    api_key = os.environ.get("PERSPECTIVE_API_KEY")
    if not api_key:
        raise ValueError("PERSPECTIVE_API_KEY environment variable not set.")

    url = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"
    params = {
        "key": api_key
    }
    headers = {
        "Content-Type": "application/json"
    }
    data = {
        "comment": {"text": text},
        "requestedAttributes": {"TOXICITY": {}}
    }

    try:
        response = requests.post(url, params=params, headers=headers, json=data)
        response.raise_for_status()  # Raise an HTTPError for bad responses (4xx or 5xx)
        result = response.json()

        if "attributeScores" in result and "TOXICITY" in result["attributeScores"]:
            score = result["attributeScores"]["TOXICITY"]["summaryScore"]["value"]
            return score < toxicity_threshold
        else:
            # If TOXICITY score is not found, default to allowing the text,
            # or raise an error depending on desired strictness.
            # For this task, we'll allow if no score is returned.
            return True
    except requests.exceptions.RequestException as e:
        print(f"Error calling Perspective API: {e}")
